update public.learning_paths
set
  title = 'International Finance',
  goal = 'International Finance',
  summary = 'This course studies exchange rates, balance of payments, international capital flows, multinational financial management, sovereign risk, and global financial crises. Students learn how currencies are traded and priced, how firms manage FX exposure, how investors allocate internationally, and how policy, institutions, and geopolitics shape global financial decisions.',
  data = $ifinjson${"slug": "international-finance", "title": "International Finance", "description": "This course studies exchange rates, balance of payments, international capital flows, multinational financial management, sovereign risk, and global financial crises. Students learn how currencies are traded and priced, how firms manage FX exposure, how investors allocate internationally, and how policy, institutions, and geopolitics shape global financial decisions.", "topics": [{"id": "0f91277f-7e3f-44bb-81b4-0fd6935a640d", "type": "topic", "title": "Global Financial System and Balance of Payments", "description": "Students learn how international payments, reserves, capital flows, and financial accounts connect firms, investors, banks, and governments.", "children": [{"id": "5f1c58ad-b50e-4cd1-a634-c31f527bf33c", "type": "subtopic", "title": "International financial architecture", "children": [{"id": "064208c1-fc3c-4522-b7d7-bdada8a33222", "type": "concept", "title": "IMF, World Bank, BIS, central banks, sovereigns, multinational firms, and global banks"}, {"id": "0b150d6a-7287-4ed1-9a87-d1723b3db548", "type": "concept", "title": "Current account, financial account, reserves, and net errors and omissions"}, {"id": "d8869f89-d9ec-4b94-bb20-26cfd5a7cb78", "type": "concept", "title": "International investment position and external balance sheets"}], "description": "The point is to see international finance as a system of institutions, markets, and rules."}, {"id": "31194598-7c07-48cc-b710-a7c33287a93d", "type": "subtopic", "title": "Balance of payments mechanics", "children": [{"id": "ca6e1011-cd00-48c7-a5dd-e3dda0c17a91", "type": "concept", "title": "Goods, services, primary income, and secondary income"}, {"id": "e355d1ee-8f2b-4091-ba43-df851e5fa88f", "type": "concept", "title": "Portfolio, direct investment, banking, and official flows"}, {"id": "3106a27c-3838-4108-8781-40733cf03b33", "type": "concept", "title": "Reserve accumulation and intervention"}], "description": "Students learn how trade, income, transfers, borrowing, lending, and reserve changes are recorded."}, {"id": "e2b02a56-04a7-4d8a-84a3-3a45a19b7ea0", "type": "subtopic", "title": "Global capital-flow patterns", "children": [{"id": "b036b6f5-9812-41f1-88ff-a99a6ea718e8", "type": "concept", "title": "Gross versus net flows"}, {"id": "74baf94c-249c-48c4-9fd2-cd74c0590d82", "type": "concept", "title": "Push and pull factors"}, {"id": "7228a009-2ac3-4337-884b-81b2a7613e41", "type": "concept", "title": "Safe assets, dollar funding, and global imbalances"}], "description": "Capital flows reveal financial integration and vulnerability."}]}, {"id": "2e284d67-07af-4ac3-a99e-8e2b99ee2b16", "type": "topic", "title": "Foreign Exchange Markets and Market Microstructure", "description": "This module explains how spot FX markets function, who trades currencies, and how liquidity, quotes, and settlement shape risk.", "children": [{"id": "aeaf022d-cb28-4a7d-91f1-30a24594962d", "type": "subtopic", "title": "Spot market fundamentals", "children": [{"id": "d6ac3a16-f829-47dd-919e-ed7d6e84ee31", "type": "concept", "title": "Direct and indirect quotes"}, {"id": "d22a3152-cafd-42f1-9048-c0daaf75b914", "type": "concept", "title": "Bid-ask spreads, pips, and cross rates"}, {"id": "a9ec2f4b-aec8-4ae1-b311-cc4184eada52", "type": "concept", "title": "Settlement, CLS, and Herstatt risk"}], "description": "Students learn how exchange rates are quoted and traded in real markets."}, {"id": "22962997-b8bc-4767-897d-bea77075b8e1", "type": "subtopic", "title": "Market participants", "children": [{"id": "ac1ec46f-f81f-4faa-8bd8-37769219a893", "type": "concept", "title": "Corporates, banks, asset managers, hedge funds, and central banks"}, {"id": "269340c9-dd9e-453d-a2cd-85c1acd4df79", "type": "concept", "title": "Interdealer and client markets"}, {"id": "8fd7bdbd-e2e8-40da-8dc5-0c172f109a44", "type": "concept", "title": "Electronic platforms and algorithmic execution"}], "description": "FX prices are shaped by commercial flows, financial flows, dealers, and policy actors."}, {"id": "e2938bf9-7004-41e4-ba43-80655edc4d52", "type": "subtopic", "title": "Liquidity and execution", "children": [{"id": "4f93364a-2940-48f4-a1b1-c3d09d121b03", "type": "concept", "title": "Market depth and order flow"}, {"id": "5c04f71c-b3b9-4e63-882b-8bd1bf971b73", "type": "concept", "title": "Liquidity during stress"}, {"id": "b0f809c3-6849-4093-b365-a7bdd3883807", "type": "concept", "title": "Transaction costs and best execution"}], "description": "Execution quality matters because currency risk is often managed at large scale."}]}, {"id": "e831de6c-f1e9-4be7-8727-59caa7934faa", "type": "topic", "title": "Exchange Rate Determination and Parity Conditions", "description": "Students build the theoretical toolkit for understanding spot rates, forward rates, interest rates, inflation, and expected currency movements.", "children": [{"id": "fca9cdcd-83c9-443c-8d20-86a5cf52191d", "type": "subtopic", "title": "Purchasing power parity", "children": [{"id": "9405a568-a9d9-4763-90a1-3893698e2b70", "type": "concept", "title": "Absolute and relative PPP"}, {"id": "6e1dc08b-b59c-4170-b2e3-cd425cc42036", "type": "concept", "title": "Real exchange rates"}, {"id": "7673036b-ec06-4354-8e32-1a5eb8ba86f7", "type": "concept", "title": "Balassa-Samuelson effect and tradable/nontradable goods"}], "description": "PPP links exchange rates to relative price levels, while showing why long-run anchors can be weak in the short run."}, {"id": "3b2f9640-88b0-46ed-bd04-844209c10836", "type": "subtopic", "title": "Interest parity", "children": [{"id": "6f5f8422-1dbd-4844-bc83-84e33db8e7ca", "type": "concept", "title": "Covered interest parity"}, {"id": "67cce80e-b143-465f-8a82-3f5e0bd9aa6f", "type": "concept", "title": "Uncovered interest parity"}, {"id": "67544cc2-07b9-4eec-b48b-5c6039257c32", "type": "concept", "title": "Forward premium puzzle"}], "description": "Parity conditions connect spot rates, forward rates, and interest differentials."}, {"id": "62311b2c-8ff6-4cb0-b1ca-f4779f0e227e", "type": "subtopic", "title": "Exchange-rate models", "children": [{"id": "07aaafe8-185c-4665-b414-0c8bb104b357", "type": "concept", "title": "Monetary approach"}, {"id": "63d6e54f-1f09-40c4-9741-cd0225a973c0", "type": "concept", "title": "Portfolio-balance models"}, {"id": "a82a1b7f-944d-48a2-80a0-26050f4fc232", "type": "concept", "title": "Expectations, news, and overshooting"}], "description": "Students compare macro, portfolio, and behavioral views of exchange-rate movement."}]}, {"id": "d71962ed-a1a7-46f5-807e-01e1c70d17d1", "type": "topic", "title": "Spot, Forward, Futures, Swaps, and Currency Derivatives", "description": "This topic develops the instruments used to hedge, speculate, fund, and transfer foreign-exchange risk.", "children": [{"id": "a5d18f18-462d-44f2-93fc-a6bf291aa36b", "type": "subtopic", "title": "FX forwards and futures", "children": [{"id": "6d586d50-e06c-4e83-a41f-d96da9659a9e", "type": "concept", "title": "Forward points and outright forwards"}, {"id": "ba2ef9a5-fd30-4092-9e05-d177f6502cae", "type": "concept", "title": "Currency futures and daily margining"}, {"id": "980e4b74-56e4-4e4d-85fa-03efc50cd1e3", "type": "concept", "title": "Basis and cross-currency basis"}], "description": "These instruments are the core tools for locking in exchange rates."}, {"id": "8023cfe5-6131-446b-919c-8e5c51393216", "type": "subtopic", "title": "FX swaps and cross-currency swaps", "children": [{"id": "57568480-881a-4bbb-bffd-517fc777508b", "type": "concept", "title": "FX swap mechanics"}, {"id": "a7701fa2-6fa8-4e63-8f33-7642a9e8451b", "type": "concept", "title": "Cross-currency interest-rate swaps"}, {"id": "d5879bba-7f3d-4180-9591-aaf2114530b0", "type": "concept", "title": "Dollar funding and swap-market stress"}], "description": "Swaps connect currency risk to funding markets and balance sheets."}, {"id": "a108574f-05e3-47d8-b48b-a9272511da87", "type": "subtopic", "title": "Currency options", "children": [{"id": "a9c0f4d1-02fd-4900-9f58-1a63c42237aa", "type": "concept", "title": "Calls, puts, collars, and participating forwards"}, {"id": "bbb1668e-5f9c-4e98-990f-04ece1f41544", "type": "concept", "title": "Implied volatility and option Greeks"}, {"id": "b60ff859-d297-4b73-aa9e-0bac3f2a2705", "type": "concept", "title": "Barrier options and structured hedges"}], "description": "Options give firms and investors asymmetric protection when certainty is too expensive or too restrictive."}]}, {"id": "6f1f1a5b-5ec1-4fcf-88ca-d314c559b5de", "type": "topic", "title": "Foreign Exchange Exposure and Hedging Strategy", "description": "Students learn how firms measure transaction, translation, and economic exposure and choose hedges that fit business objectives.", "children": [{"id": "0937e9cb-1328-418e-a55f-8d28609af406", "type": "subtopic", "title": "Exposure types", "children": [{"id": "d9391a69-ee50-4ffb-ab28-96371330d7a6", "type": "concept", "title": "Transaction exposure"}, {"id": "b1979184-247f-4b42-8558-12d2aed66ef6", "type": "concept", "title": "Translation exposure"}, {"id": "f4b68462-1500-4f35-aeb7-5c6798a80040", "type": "concept", "title": "Economic and competitive exposure"}], "description": "Students learn to identify what kind of currency risk is actually present."}, {"id": "6106663d-f66a-4f52-a0fe-053029f78fa6", "type": "subtopic", "title": "Hedging instruments", "children": [{"id": "95e31a30-e51d-4feb-98e9-599fc6b4cf21", "type": "concept", "title": "Forwards, futures, options, swaps, and natural hedges"}, {"id": "b1e990c7-dda9-4d49-b6a8-ae766d221013", "type": "concept", "title": "Money-market hedges and leading/lagging"}, {"id": "05aad541-7a88-4eb4-8e2d-74ccab2fb03a", "type": "concept", "title": "Netting, matching, and centralized treasury"}], "description": "The gist is matching hedge design to exposure, accounting, liquidity, and governance."}, {"id": "f94624e9-92ef-4cf5-b5f4-f184c618517e", "type": "subtopic", "title": "Hedge policy and evaluation", "children": [{"id": "b4458376-2ca0-42ec-bd9c-46f83462fd50", "type": "concept", "title": "Hedge ratios and hedge horizon"}, {"id": "6d235066-8828-4edc-85f0-3e12089436ce", "type": "concept", "title": "Cost of hedging and opportunity cost"}, {"id": "956abbc5-fce3-48b0-8bb5-179672cb60d6", "type": "concept", "title": "Hedge effectiveness, reporting, and board policy"}], "description": "A hedge program must be measurable, governed, and explainable."}]}, {"id": "0a551b17-81c6-481c-b557-92a63ab278bf", "type": "topic", "title": "International Capital Budgeting and Cross-Border Valuation", "description": "This module adapts valuation and capital budgeting to foreign cash flows, taxes, political risk, and exchange-rate uncertainty.", "children": [{"id": "a2846fc6-8181-4cf8-909d-56df397b91d2", "type": "subtopic", "title": "Foreign project cash flows", "children": [{"id": "b71a227f-8b8f-4ee7-ba52-8a47563317a2", "type": "concept", "title": "Parent versus project cash flows"}, {"id": "7d0ab7e3-8ae1-49c9-8ddb-94dd4e3274ab", "type": "concept", "title": "Repatriation, withholding taxes, and blocked funds"}, {"id": "df7794f1-6a83-4e5b-865a-43bc5de6e96f", "type": "concept", "title": "Transfer pricing and royalties"}], "description": "Students adapt capital budgeting to foreign revenues, costs, taxes, and remittances."}, {"id": "b9e00378-0827-4583-8e76-0149e03ce880", "type": "subtopic", "title": "Currency and country risk in valuation", "children": [{"id": "66e48349-ab79-4333-a502-92a8bbd34ec3", "type": "concept", "title": "Local-currency versus home-currency valuation"}, {"id": "bc74aea4-5115-4e0b-90d2-4cf31321fe49", "type": "concept", "title": "Real versus nominal cash flows"}, {"id": "7b76a4a1-a8ca-4c2a-94e3-1bf224feaa0a", "type": "concept", "title": "Country risk premiums and sovereign spreads"}], "description": "Cross-border valuation requires consistency between cash flows, discount rates, and exchange-rate assumptions."}, {"id": "9a69ab47-60c5-4798-b701-b55c5f2f36f8", "type": "subtopic", "title": "Strategic optionality", "children": [{"id": "b4052a85-b708-4490-b667-75e9505715c2", "type": "concept", "title": "Staged investment"}, {"id": "8d69ee47-ad10-414e-bfde-5759039f7540", "type": "concept", "title": "Abandonment and expansion options"}, {"id": "d62f1199-2dd7-4ec0-a0c8-9cc503da1ade", "type": "concept", "title": "Scenario analysis and sensitivity tables"}], "description": "International projects often embed real options and political contingencies."}]}, {"id": "689ef0f5-92a1-4770-9f05-2189f7963b84", "type": "topic", "title": "Multinational Capital Structure, Funding, and Treasury Management", "description": "Students study how multinationals finance subsidiaries, manage liquidity, and optimize capital structure across currencies and jurisdictions.", "children": [{"id": "b8ad641c-c784-46a6-9636-f0e8af4ace72", "type": "subtopic", "title": "Global funding choices", "children": [{"id": "542c1d04-c2be-40dd-b8a3-8e7ef2db715c", "type": "concept", "title": "Local debt versus parent debt"}, {"id": "55b130fa-2ed4-4445-8d5f-8dbdf05dc998", "type": "concept", "title": "Eurobond and global bond markets"}, {"id": "dd4a489f-1d6f-4749-8fc5-c154bfbcfeae", "type": "concept", "title": "Bank loans, commercial paper, and intercompany loans"}], "description": "Multinationals choose where and how to raise capital across markets."}, {"id": "f68117eb-3e24-4ed7-a97d-b35588737ff6", "type": "subtopic", "title": "Capital structure across countries", "children": [{"id": "e2a906c7-ae22-4be0-88b3-704da9f2c6ff", "type": "concept", "title": "Tax shields and thin-capitalization rules"}, {"id": "8f3168a2-186a-4797-8b94-04230648bd0c", "type": "concept", "title": "Agency costs and creditor rights"}, {"id": "d299c9ee-8535-4381-bc40-1dc42c63fcd7", "type": "concept", "title": "Currency matching of debt and assets"}], "description": "Optimal leverage varies with taxes, legal systems, currency risk, and market depth."}, {"id": "a9e7364f-6c7e-469f-bf4a-e074e3e9bc5b", "type": "subtopic", "title": "Treasury operations", "children": [{"id": "0ae1f0d7-ed60-4407-947a-de3d7e63c4fe", "type": "concept", "title": "Cash pooling and liquidity management"}, {"id": "3627cfc2-be75-408e-8d92-cef3e521d38f", "type": "concept", "title": "Working capital across borders"}, {"id": "7460b1f5-2e76-4c8a-b0af-a59156b01e99", "type": "concept", "title": "Treasury centers and in-house banks"}], "description": "Treasury links financing, liquidity, risk, and governance."}]}, {"id": "c530a6c7-d740-4f06-8336-330873c8102f", "type": "topic", "title": "International Portfolio Investment and Currency Overlay", "description": "This topic covers global asset allocation, diversification, hedged versus unhedged returns, and currency overlay decisions.", "children": [{"id": "e8904b7f-81e2-4471-a227-66823d08c863", "type": "subtopic", "title": "Global diversification", "children": [{"id": "311b4ff6-f4e2-4a22-8e79-a4939e645295", "type": "concept", "title": "Home bias"}, {"id": "581e2e15-cc39-4810-9c80-369df252d31f", "type": "concept", "title": "Country, sector, and currency allocation"}, {"id": "7c4931f2-5c09-4c9f-b4e3-f6e738a731dc", "type": "concept", "title": "Correlation, contagion, and crisis regimes"}], "description": "Students learn when international diversification reduces risk and when correlations rise."}, {"id": "b20a8377-28e4-469d-9a12-bd3fd3b6bd45", "type": "subtopic", "title": "Currency return and risk", "children": [{"id": "2705372a-1203-401e-a909-52f488587db5", "type": "concept", "title": "Hedged versus unhedged returns"}, {"id": "f8fe1df3-8b14-4958-9dec-9a67ece6ce2b", "type": "concept", "title": "Carry, momentum, and value strategies"}, {"id": "56df338c-8167-4460-a356-dd228c918a25", "type": "concept", "title": "Currency risk premia"}], "description": "Currency can be an asset, a risk factor, or a hedge."}, {"id": "cb6763de-a59c-4911-a916-550c00e0ef34", "type": "subtopic", "title": "Currency overlay", "children": [{"id": "570078a4-39a6-4bcb-b0d0-18c5e388e569", "type": "concept", "title": "Passive hedge ratios"}, {"id": "d6cf8d85-f92a-46d0-bb12-022510077a33", "type": "concept", "title": "Active overlay mandates"}, {"id": "98a32702-df0f-4a02-8e66-929214da5b54", "type": "concept", "title": "Benchmarking and performance attribution"}], "description": "Professional investors separate asset allocation from currency management."}]}, {"id": "b11f0ff5-3b1b-4930-8f6a-f40421f8708d", "type": "topic", "title": "Sovereign Debt, Country Risk, and Political Risk", "description": "Students learn how sovereign risk, institutions, governance, and geopolitics affect capital flows, returns, and corporate decisions.", "children": [{"id": "f4fb3348-d1ac-468d-ae53-ff1963f46f81", "type": "subtopic", "title": "Sovereign debt analysis", "children": [{"id": "c22c8cc3-ffa9-4513-9d53-8030489b125c", "type": "concept", "title": "Debt sustainability"}, {"id": "d1987512-a981-4680-9b8f-721cd08c8cae", "type": "concept", "title": "Local-currency versus foreign-currency debt"}, {"id": "f4e86f66-c378-4b71-8205-700ed3c3f4a6", "type": "concept", "title": "Default, restructuring, and collective action clauses"}], "description": "Students learn how governments borrow, repay, restructure, and affect market risk."}, {"id": "e3973cd4-0e91-4ad8-8a5f-51fcee83544d", "type": "subtopic", "title": "Country risk assessment", "children": [{"id": "2566f67f-e9ce-44d0-b7ac-cea5d148a40e", "type": "concept", "title": "Inflation, reserves, current account, and fiscal balance"}, {"id": "0da24d32-528f-4861-9c41-5875f9536679", "type": "concept", "title": "Governance, rule of law, and policy credibility"}, {"id": "9d077488-739e-4deb-ba67-a74912194968", "type": "concept", "title": "Ratings, spreads, and market-implied risk"}], "description": "Country risk blends macro, financial, institutional, and legal signals."}, {"id": "44d241f2-fc09-473e-ab2b-ec08bde1dbf5", "type": "subtopic", "title": "Political and geopolitical risk", "children": [{"id": "e162a4d2-dd36-48ba-87d7-ac0334067f65", "type": "concept", "title": "Expropriation, sanctions, capital controls, and war risk"}, {"id": "98f32918-23e6-40e6-9e5b-8e9fbc89ea69", "type": "concept", "title": "Election risk and policy uncertainty"}, {"id": "3fae7586-875f-454e-959d-9cb02b742158", "type": "concept", "title": "Scenario planning and risk mitigation"}], "description": "Political shocks can reshape currency values and capital-market access."}]}, {"id": "2e7382bf-fd77-467f-813a-1765402348a5", "type": "topic", "title": "Emerging Markets Finance and Global Banking", "description": "This module examines the distinctive risks of emerging markets, cross-border banking, financial development, and regulatory systems.", "children": [{"id": "f9952fe3-9108-4c61-95f3-3b01538918a8", "type": "subtopic", "title": "Emerging-market characteristics", "children": [{"id": "bd433dad-148e-48bb-9a61-d7181b1f576c", "type": "concept", "title": "Shallow markets and liquidity risk"}, {"id": "a4b715b2-30fa-414c-8ebd-28f6d86b5e32", "type": "concept", "title": "Inflation, dollarization, and original sin"}, {"id": "7636840f-c324-4ca0-99fa-3b5a8ac8bda3", "type": "concept", "title": "Institutional quality and financial development"}], "description": "Emerging markets offer growth and diversification, but with distinctive frictions."}, {"id": "6c136d34-c88c-4693-a7c8-5e4bf8383967", "type": "subtopic", "title": "Global banking", "children": [{"id": "ea1294ce-a025-4b61-b087-3a1801b3c099", "type": "concept", "title": "Correspondent banking"}, {"id": "49df30a9-7f6c-4fb9-a612-ca4112f95975", "type": "concept", "title": "Cross-border claims and BIS banking statistics"}, {"id": "185cf719-0240-463f-bab0-b83748be3b50", "type": "concept", "title": "Regulatory arbitrage and ring-fencing"}], "description": "Cross-border banking transmits credit, funding, and regulatory shocks."}, {"id": "6e6b34c9-221c-44ca-a3bb-a0dbd1b11a89", "type": "subtopic", "title": "Development and inclusion", "children": [{"id": "d0e33a24-6bbb-400e-b6c7-092cd03eb156", "type": "concept", "title": "Capital-market development"}, {"id": "1959da02-ed70-4f2c-82df-07b2ec653700", "type": "concept", "title": "Microfinance and fintech rails"}, {"id": "25aefc64-f376-4bcc-b961-f0dd182351d3", "type": "concept", "title": "Infrastructure finance and blended finance"}], "description": "International finance also shapes real development and access to capital."}]}, {"id": "4aa331f7-a28d-4484-ad3f-cc8ec0d7ed61", "type": "topic", "title": "International Monetary System and Currency Regimes", "description": "Students analyze fixed, floating, managed, dollarized, and monetary-union regimes through the lens of policy tradeoffs.", "children": [{"id": "71bb02fd-edad-4a7a-83ee-0d2488e2e657", "type": "subtopic", "title": "Exchange-rate regimes", "children": [{"id": "efa20689-38ef-4b0f-af9b-dd51ff06891f", "type": "concept", "title": "Currency boards, pegs, bands, and managed floats"}, {"id": "6616bd31-ed65-4d40-9b27-4e8599edf0e1", "type": "concept", "title": "Dollarization and monetary unions"}, {"id": "0821aaab-55ad-4bb9-9ef4-37ca07ad2697", "type": "concept", "title": "Regime credibility and reserve adequacy"}], "description": "Students compare policy tradeoffs under fixed, floating, and intermediate regimes."}, {"id": "9d1dd525-f048-42b2-b842-93a6c096e36e", "type": "subtopic", "title": "Impossible trinity", "children": [{"id": "e95a1f5d-c0a7-44d1-9eb6-801fa125555b", "type": "concept", "title": "Capital mobility"}, {"id": "509c252c-65be-4bff-a48a-27e8cdab714e", "type": "concept", "title": "Monetary independence"}, {"id": "6b1a4a87-4b56-4683-972a-350108ddc9c3", "type": "concept", "title": "Exchange-rate stability"}], "description": "The trilemma explains why policy autonomy, fixed exchange rates, and free capital mobility cannot all coexist."}, {"id": "5a44471f-cf45-494b-b82b-de1e68e5dabe", "type": "subtopic", "title": "International monetary history", "children": [{"id": "29f2b455-1b01-4109-b8c4-fc7a51a09ccc", "type": "concept", "title": "Gold standard"}, {"id": "b4019c63-5342-41c1-a3ac-3f83cb4fdc77", "type": "concept", "title": "Bretton Woods"}, {"id": "9d43d0f0-c3ab-4d85-8344-f34fb94a976d", "type": "concept", "title": "Post-1973 floating and modern reserve-currency system"}], "description": "Historical regimes show how institutions evolve under crisis pressure."}]}, {"id": "be41edc6-d6fc-41f5-97dd-d45618aac83a", "type": "topic", "title": "Capital Flows, Financial Crises, and Contagion", "description": "This topic explains sudden stops, currency crises, banking crises, debt crises, and the channels through which stress crosses borders.", "children": [{"id": "9fec1bd4-60e6-4314-ae34-f39fe00c19bc", "type": "subtopic", "title": "Currency crises", "children": [{"id": "0e95444a-2242-410b-b6ad-a3b6a964d625", "type": "concept", "title": "First-, second-, and third-generation crisis models"}, {"id": "42f67561-8665-4013-9664-d456fefe950e", "type": "concept", "title": "Reserve loss and speculative attacks"}, {"id": "cc5b68af-03ad-4de8-bd64-cf791a64ab16", "type": "concept", "title": "Balance-sheet effects"}], "description": "Students learn why pegs break and why expectations can become self-fulfilling."}, {"id": "a1bcdddd-71bb-4500-8dee-003ace22812f", "type": "subtopic", "title": "Debt and banking crises", "children": [{"id": "a9d151aa-85bb-4a8c-aeea-8912c037c9ff", "type": "concept", "title": "Twin crises"}, {"id": "d0985d7d-d2b3-446e-b8f7-000007ae7d2c", "type": "concept", "title": "Sudden stops"}, {"id": "4c72ab71-dd11-466c-bfde-65ce57df7ab9", "type": "concept", "title": "Sovereign-bank doom loops"}], "description": "External finance can amplify banking and sovereign fragility."}, {"id": "0900ac3e-7147-42b1-a6fe-a2ca2e7243ae", "type": "subtopic", "title": "Contagion and crisis response", "children": [{"id": "7dedbb97-9a7b-46a1-a75e-1e0d5d7480ee", "type": "concept", "title": "Capital controls and macroprudential tools"}, {"id": "2192886f-ec1a-4993-8b99-9ee6083ef08b", "type": "concept", "title": "IMF programs and conditionality"}, {"id": "b158146a-df55-4ad1-8977-f98a1d8ea213", "type": "concept", "title": "Lender of last resort and swap lines"}], "description": "Crises spread through trade, finance, expectations, and policy channels."}]}, {"id": "c88714a4-c5c5-4f22-8bd1-2b30c938f513", "type": "topic", "title": "Macroeconomic Policy, Central Banks, and Global Financial Conditions", "description": "Students connect monetary policy, fiscal policy, inflation, real exchange rates, and global dollar liquidity to market outcomes.", "children": [{"id": "1faf5fc2-76bb-42d6-8e76-7b65226dfcbc", "type": "subtopic", "title": "Policy transmission", "children": [{"id": "e0997d60-fb96-49e0-b108-57b778ba49ba", "type": "concept", "title": "Interest rates, inflation, and real exchange rates"}, {"id": "598ce127-0792-4c34-a04f-c45d63c6bec8", "type": "concept", "title": "Fiscal sustainability and external confidence"}, {"id": "5c2d8e55-4def-46cf-8237-30d8587d67f3", "type": "concept", "title": "Monetary-policy spillovers"}], "description": "Domestic policy affects currencies, capital flows, and cross-border valuations."}, {"id": "c84c6488-2497-4685-bf4d-e9efa375ba8d", "type": "subtopic", "title": "Global financial cycle", "children": [{"id": "f0806841-3b01-4588-9149-a88d2081ff20", "type": "concept", "title": "VIX, risk premia, and capital-flow waves"}, {"id": "65f7345b-7ed6-4a83-8653-f87f231afebc", "type": "concept", "title": "Federal Reserve spillovers"}, {"id": "6c7080b2-94f4-4e50-bc64-b839d60c9ee5", "type": "concept", "title": "Dollar funding markets and swap lines"}], "description": "Global risk appetite and dollar liquidity constrain national financial conditions."}, {"id": "bd651679-3959-44c1-ad6c-c3aa4e998b34", "type": "subtopic", "title": "Policy analysis for investors and firms", "children": [{"id": "d9489f36-98fb-43e2-a239-8d5b07a52c8a", "type": "concept", "title": "Country and currency scenarios"}, {"id": "eb08c44f-c8ae-4add-a7cb-97255b941d04", "type": "concept", "title": "Rates, FX, and sov